  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].k === 'o' && toks[p].v === v
  const bad = new Error('syntax')
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'o' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw bad
    const t = toks[p++]
    if (t.k === 'n') return { n: 'num', v: t.v }
    if (t.k === 'o') {
      if (t.v === '(') { const e = cmp(); if (!isOp(')')) throw bad; p++; return e }
      throw bad
    }
    const up = t.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++; return { n: 'call', name: up, args } }
      for (;;) {
        args.push(cmp())
        if (isOp(',')) { p++; continue }
        if (isOp(')')) { p++; break }
        throw bad
      }
      return { n: 'call', name: up, args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'w') throw bad
      return { n: 'range', a: t.v, b: toks[p++].v }
    }
    if (up === 'TRUE') return { n: 'bool', v: true }
    if (up === 'FALSE') return { n: 'bool', v: false }
    return { n: 'ref', w: t.v }
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (x) {
    if (x === bad) return null
    throw x
  }
}

// range misplaced check
function rangesOk(n, direct) {
  switch (n.n) {
    case 'range': return direct
    case 'bin': return rangesOk(n.l, false) && rangesOk(n.r, false)
    case 'un': return rangesOk(n.e, false)
    case 'call': return n.args.every((a) => rangesOk(a, true))
    default: return true
  }
}

// ---- cell classification
const info = new Map()
for (const [key, c] of cells) {
  const s = c.content
  if (s[0] === '=') {
    const ast = parseFormula(s.slice(1))
    info.set(key, ast ? { kind: 'f', ast, ok: rangesOk(ast, false) } : { kind: 'f', ast: null, ok: false })
  } else if (s === '') info.set(key, { kind: 'v', val: num(0) })
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) info.set(key, { kind: 'v', val: num(Number(s)) })
  else if (ERRS.includes(s)) info.set(key, { kind: 'v', val: err(s) })
  else info.set(key, { kind: 'v', val: { t: 'text', v: s } })
}

// ---- deps
function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: c, row: r, key: keyOf(c, r) })
  return out
}
function collect(n, set) {
  switch (n.n) {
    case 'ref': { const a = parseAddr(n.w); if (a) set.set(a.key, a); break }
    case 'range': { for (const a of rangeCells(n.a, n.b) || []) set.set(a.key, a); break }
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'un': collect(n.e, set); break
    case 'call': n.args.forEach((a) => collect(a, set)); break
  }
}

const order = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)

if (mode === 'deps') {
  let out = ''
  for (const c of order) {
    const key = keyOf(c.col, c.row)
    const f = info.get(key)
    const set = new Map()
    if (f.kind === 'f' && f.ast) collect(f.ast, set)
    const list = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out += key + ':' + list.map((a) => ' ' + a.key).join('') + '\n'
  }
  process.stdout.write(out)
  process.exit(0)
}

// ---- evaluation
const memo = new Map()
const busy = new Set()
function cellValue(key) {
  if (memo.has(key)) return memo.get(key)
  const f = info.get(key)
  if (!f) return num(0)
  if (f.kind === 'v') return f.val
  if (busy.has(key)) return err('#CYCLE!')
  busy.add(key)
  let v
  if (!f.ok) v = ERR
  else v = evalNode(f.ast)
  busy.delete(key)
  memo.set(key, v)
  return v
}
function refValue(w) {
  const a = parseAddr(w)
  return a ? cellValue(a.key) : err('#REF!')
}
function toNum(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = { num: 0, text: 1, bool: 2 }

function compare(op, l, r) {
  let c
  if (l.t !== r.t) c = rank[l.t] - rank[r.t]
  else if (l.t === 'bool') c = Number(l.v) - Number(r.v)
  else c = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[op]
  return { t: 'bool', v: res }
}

function argValues(args) {
  const out = []
  for (const a of args) {
    if (a.n === 'range') {
      const cs = rangeCells(a.a, a.b)
      if (!cs) out.push(err('#REF!'))
      else for (const c of cs) out.push(cellValue(c.key))
    } else out.push(evalNode(a))
  }
  return out
}

function evalNode(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'bool', v: n.v }
    case 'ref': return refValue(n.w)
    case 'range': return ERR
    case 'un': {
      const v = evalNode(n.e)
      if (v.t === 'err') return v
      const x = toNum(v)
      if (x.t === 'err') return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const l = evalNode(n.l)
      const r = evalNode(n.r)
      if (l.t === 'err') return l
      if (r.t === 'err') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) return compare(n.op, l, r)
      const a = toNum(l)
      if (a.t === 'err') return a
      const b = toNum(r)
      if (b.t === 'err') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
      return ERR
    }
    case 'call': return evalCall(n)
  }
  return ERR
}

function evalCall(n) {
  const k = n.args.length
  const name = n.name
  if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) {
    if (k < 1) return ERR
    const vals = argValues(n.args)
    const e = vals.find((v) => v.t === 'err')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'err') return x
      nums.push(x.v)
    }
    if (name === 'SUM') return fin(nums.reduce((a, b) => a + b, 0))
    if (name === 'MIN') return num(Math.min(...nums))
    if (name === 'MAX') return num(Math.max(...nums))
    return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
  if (name === 'ABS') {
    if (k !== 1) return ERR
    const vals = argValues(n.args)
    if (vals.length !== 1) return ERR
    if (vals[0].t === 'err') return vals[0]
    const x = toNum(vals[0])
    return x.t === 'err' ? x : num(Math.abs(x.v))
  }
  if (name === 'IF') {
    if (k !== 3) return ERR
    const cv = argValues([n.args[0]])
    if (cv.length !== 1) return ERR
    const c = cv[0]
    if (c.t === 'err') return c
    let b
    if (c.t === 'bool') b = c.v
    else if (c.t === 'num') b = c.v !== 0
    else return err('#VALUE!')
    const br = argValues([n.args[b ? 1 : 2]])
    return br.length === 1 ? br[0] : ERR
  }
  return err('#NAME?')
}

function fmt(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

let out = ''
for (const c of order) {
  const key = keyOf(c.col, c.row)
  out += key + '=' + fmt(cellValue(key)) + '\n'
}
process.stdout.write(out)
